let apollo11Hypothesis = { Id = "2b7c50ea-9029-51fe-9f40-d788fc54b423"; Statement = "The 1202 and 1201 alarms were Executive overflows caused by counter interrupts from the rendezvous radar coupling data units, which stole more than 10 percent of the computer's capacity."; State = "supported"; Mechanism = Some "With the rendezvous radar mode switch in AUTO or SLEW (the configuration the procedures called for; whether the procedure or the interface specification was at fault is contested), resolver excitation came from a 28-volt 800-hertz supply frequency-locked but not phase-locked to the guidance reference; the CDUs slewed and sent continuous pulses to the computer (A11-C031, A11-C032, A11-C033). Repetitive jobs were then scheduled again before earlier copies completed, overflowing the Executive (A11-C029, A11-C030, A11-C034): 1202 when no core sets and 1201 when no VAC areas were free, both Executive bailout alarms (A11-C118). The mechanism was established by post-flight analysis and simulation; on the surface it was a hedged working hypothesis (A11-C102)." }
