      { Id = "040b1f79-4cfd-5574-89bc-97bf3387eebb"; Content = "Excerpt: \"We had the rendezvous radar switch in the Slew position, not the LGC position.\"\nParaphrase: Aldrin told Houston from the surface that the rendezvous radar switch had been in Slew, not LGC, during descent.\nTime basis: Voice-transcript GET 121:42:21 + range zero 1969-07-16T13:32:00Z (Mission Report MSC-00171 sec. 2.0, claim A11-C001); transcript times are ground-clock annotations accurate to about 1-2 s and ALSJ notes inconsistencies in the original NASA transcript times\nNote: ALSJ corrected transcript line (real-time communication, transcript corrected by the ALSJ editor from audio); bracketed text is editorial."; Category = Some "log"; Source = Some "The Return to Orbit (Eric M. Jones (ed.), Apollo 11 Lunar Surface Journal, 2026-10-13, Apollo 11 Lunar Surface Journal (last revised 13 October 2026)), GET 121:42:21. https://www.apollojournals.org/alsj/a11/a11.launch.html [claim A11-C038; source A11-S09; primary source; retrieved 2026-10-23]"; CapturedAt = Some "1969-07-21T15:14:21.000Z" }
      { Id = "11fddb10-b4fb-539f-b66e-129a4acb393b"; Content = "Excerpt: \"The attitude and translation control assembly voltage is locked in frequency with the primary guidance and navigation system voltage through the system's control of the PCM and timing electronics frequency, but it is not locked in phase.\"\nParaphrase: With the rendezvous radar mode switch in AUTO or SLEW, resolver excitation came from the ATCA 28-volt 800-hertz supply, which was frequency-locked but not phase-locked to the PGNS 800-hertz reference; phase/amplitude differences made the CDUs slew digitally and send continuous pulses to the computer.\nNote: Excerpt transcribed from the OCR text layer of the scanned report; OCR letter-spacing artifacts normalized, wording unchanged. Physical mechanism as officially documented."; Category = Some "experimentResult"; Source = Some "Apollo 11 Mission Report (NASA Manned Spacecraft Center, Houston, Texas, 1969-11, MSC-00171 (NASA-TM-X-62633; NTRS 19700008096)), Section 16.2.5, p. 16-13. https://www.apollojournals.org/alsj/a11/A11_MissionReport.pdf [claim A11-C032; source A11-S01; primary source; retrieved 2026-10-23]"; CapturedAt = None }
